/// A Plot of a header under `fixtures/wcsconv/inputs`, or of a 2-D Frame.
fn plot_of(head: Option<&str>, gbox: [f32; 4], pbox: [f64; 4]) -> Plot {
    match head {
        Some(head) => Plot::new(&read_head(head), gbox, pbox).unwrap(),
        None => Plot::new(&BasicFrameBuilder::new(2).build().unwrap(), gbox, pbox).unwrap(),
    }
}

/// The call log and SVG of drawing on `plot` with `draw`, each from its own
/// copy of the Plot.
fn log_and_svg(
    plot: &Plot,
    mut draw: impl FnMut(&mut Plot, &mut dyn Grf) -> AstResult<()>,
) -> (String, String) {
    let mut log = LogGrf::new(Vec::new());
    draw(&mut plot.clone(), &mut log).unwrap();
    let log = String::from_utf8(log.finish().unwrap()).unwrap();
    let mut svg = SvgGrf::new(Vec::new(), SvgOptions::default()).unwrap();
    draw(&mut plot.clone(), &mut svg).unwrap();
    let svg = String::from_utf8(svg.finish().unwrap()).unwrap();
    (log, svg)
}

/// The first line at which two texts differ, for a failure message, with
/// long lines shortened.
fn first_difference(got: &str, want: &str) -> String {
    let short = |s: &str| s.chars().take(160).collect::<String>();
    for (i, (g, w)) in got.lines().zip(want.lines()).enumerate() {
        if g != w {
            return format!("line {}: got {:?}, C gives {:?}", i + 1, short(g), short(w));
        }
    }
    format!(
        "{} lines, C gives {}",
        got.lines().count(),
        want.lines().count()
    )
}

/// An SVG a probe recorded: its text, or the hash of a long one.
enum WantSvg {
    Text(&'static str),
    Hash(u64),
}

impl From<&curve::Svg> for WantSvg {
    fn from(svg: &curve::Svg) -> Self {
        match svg {
            curve::Svg::Text(t) => WantSvg::Text(t),
            curve::Svg::Fnv1a(h) => WantSvg::Hash(*h),
        }
    }
}

impl From<&text::Svg> for WantSvg {
    fn from(svg: &text::Svg) -> Self {
        match svg {
            text::Svg::Text(t) => WantSvg::Text(t),
            text::Svg::Fnv1a(h) => WantSvg::Hash(*h),
        }
    }
}

impl From<&methods::Svg> for WantSvg {
    fn from(svg: &methods::Svg) -> Self {
        match svg {
            methods::Svg::Text(t) => WantSvg::Text(t),
            methods::Svg::Fnv1a(h) => WantSvg::Hash(*h),
        }
    }
}

impl From<&border::Svg> for WantSvg {
    fn from(svg: &border::Svg) -> Self {
        match svg {
            border::Svg::Text(t) => WantSvg::Text(t),
            border::Svg::Fnv1a(h) => WantSvg::Hash(*h),
        }
    }
}

/// Compare a drawing's log and SVG with C's, adding any difference to
/// `failures`.
fn compare(
    name: &str,
    log: &str,
    svg: &str,
    want_log: &str,
    want_svg: WantSvg,
    failures: &mut Vec<String>,
) {
    if log != want_log {
        failures.push(format!("{name}: log {}", first_difference(log, want_log)));
    }
    match want_svg {
        WantSvg::Text(want) if svg != want => {
            failures.push(format!("{name}: SVG {}", first_difference(svg, want)));
        }
        WantSvg::Hash(want) if fnv1a(svg) != want => {
            failures.push(format!(
                "{name}: SVG differs from C's, whose hash is recorded"
            ));
        }
        _ => {}
    }
}

#[test]
fn grid_lines_match_the_c_library() {
    let mut failures = Vec::new();
    for case in curve::CASES {
        let mut plot = plot_of(case.head, case.gbox, case.pbox);
        apply_settings(&mut plot, case.attr).unwrap();
        let (log, svg) = log_and_svg(&plot, |plot, grf| {
            for &(axis, start, length) in case.lines {
                plot.draw_grid_line(grf, axis, &start, length)?;
            }
            Ok(())
        });
        compare(
            case.name,
            &log,
            &svg,
            case.log,
            (&case.svg).into(),
            &mut failures,
        );
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn draw_grid_line_rejects_an_invalid_axis() {
    let mut plot = plot_of(None, [0.1, 0.1, 0.9, 0.9], [0.0, 0.0, 10.0, 10.0]);
    let mut grf = LogGrf::new(Vec::new());
    let err = plot
        .draw_grid_line(&mut grf, 3, &[1.0, 1.0], 2.0)
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Axiin);
}

/// The Plot of a border case: a grid test case, or one of the probe's 2-D
/// Frame Plots.
fn border_plot(name: &str) -> Plot {
    let gbox = [0.1, 0.1, 0.9, 0.9];
    let pbox = [0.0, 0.0, 10.0, 10.0];
    match name {
        "frame" => plot_of(None, gbox, pbox),
        "frame_log" => {
            let mut plot = plot_of(None, gbox, [1.0, 0.0, 1000.0, 10.0]);
            apply_settings(&mut plot, "LogPlot(1)=1").unwrap();
            plot
        }
        "frame_styles" => {
            let mut plot = plot_of(None, gbox, pbox);
            apply_settings(
                &mut plot,
                "Width(border)=2,Colour(border)=4,Style(border)=3",
            )
            .unwrap();
            plot
        }
        "car3_3d" => car3_3d(),
        _ if name.starts_with("region_") => region_plot(name),
        _ => testgrid_plot(grid_cases().iter().find(|c| c.name == name).unwrap()),
    }
}

/// A Plot whose current Frame is a Region, as the border probe builds it:
/// of a 2-D Frame with a plot box of 0 to 10 on each axis, unless the Region
/// is on the sky.
fn region_plot(name: &str) -> Plot {
    let gbox = [0.1, 0.1, 0.9, 0.9];
    let mut pbox = [0.0, 0.0, 10.0, 10.0];
    let f2 = || BasicFrameBuilder::new(2).build().unwrap();
    let circle = |f, c: [f64; 2], r| -> DynRegion {
        Box::new(
            CircleBuilder::new(f, c.to_vec())
                .unwrap()
                .radius(r)
                .build()
                .unwrap(),
        )
    };
    let region: DynRegion = match name {
        "region_circle" => circle(f2(), [5.0, 5.0], 3.0),
        "region_sky_circle" => {
            pbox = [0.9, 0.4, 1.1, 0.6];
            Box::new(
                CircleBuilder::new(SkyFrame::new(SkySystem::Icrs), vec![1.0, 0.5])
                    .unwrap()
                    .radius(0.05)
                    .build()
                    .unwrap(),
            )
        }
        "region_box" => Box::new(
            BoxRegionBuilder::from_bounds(f2(), &[2.0, 3.0], &[7.0, 6.0])
                .unwrap()
                .build()
                .unwrap(),
        ),
        "region_or_disjoint" => Box::new(
            CmpRegionBuilder::from_dyn(
                circle(f2(), [3.0, 3.0], 1.5),
                circle(f2(), [7.0, 7.0], 1.5),
                CmpOperator::Or,
            )
            .unwrap()
            .build()
            .unwrap(),
        ),
        "region_neg_circle" => {
            let mut reg = circle(f2(), [5.0, 5.0], 3.0);
            reg.negate();
            reg
        }
        "region_prism" => {
            let f1 = || BasicFrameBuilder::new(1).build().unwrap();
            let interval = |lo: f64, hi: f64| {
                IntervalBuilder::new(f1(), vec![lo], vec![hi])
                    .unwrap()
                    .build()
                    .unwrap()
            };
            Box::new(
                PrismBuilder::new(interval(2.0, 8.0), interval(3.0, 7.0))
                    .unwrap()
                    .build()
                    .unwrap(),
            )
        }
        "region_ellipse" => Box::new(
            EllipseBuilder::new(f2(), vec![5.0, 5.0], [3.0, 1.5], 0.5)
                .unwrap()
                .build()
                .unwrap(),
        ),
        "region_polygon" => {
            let xs = [2.0, 5.0, 8.0, 9.5, 8.0, 5.0, 2.6];
            let ys = [2.0, 0.5, 2.0, 5.0, 8.0, 7.4, 5.0];
            let vertices = xs.iter().zip(&ys).map(|(&x, &y)| vec![x, y]).collect();
            Box::new(
                PolygonBuilder::new(f2(), vertices)
                    .unwrap()
                    .build()
                    .unwrap(),
            )
        }
        "region_moc" => {
            pbox = [0.3, -0.05, 1.27, 0.8];
            let mut moc = Moc::new();
            moc.add_moc_string(CmpOperator::Or, false, -1, "3/0-2,4-5,7-8,10-11,13-15")
                .unwrap();
            Box::new(moc)
        }
        "region_gal_circle" => {
            pbox = [2.78, -0.42, 2.94, -0.27];
            let mut circle = CircleBuilder::new(SkyFrame::new(SkySystem::Icrs), vec![1.0, 0.5])
                .unwrap()
                .radius(0.05)
                .build()
                .unwrap();
            circle
                .with_integrity(|f| {
                    f.as_any_mut()
                        .downcast_mut::<SkyFrame>()
                        .expect("a sky Circle's Frame is a SkyFrame")
                        .set_system(SkySystem::Galactic);
                    Ok(())
                })
                .unwrap();
            Box::new(circle)
        }
        other => panic!("no region Plot {other}"),
    };
    Plot::new(region.as_ref(), gbox, pbox).unwrap()
}

/// The car3 grid test Plot with a 3-D current Frame added: a CmpFrame of
/// its sky Frame and a 1-D Frame, joined by a PermMap giving the third
/// axis 0, as the border probe builds it.
fn car3_3d() -> Plot {
    let mut plot = testgrid_plot(grid_cases().iter().find(|c| c.name == "car3").unwrap());
    let sky = plot.frameset().current().snapshot();
    let one = Box::new(BasicFrameBuilder::new(1).build().unwrap());
    let cube = CmpFrame::new(sky, one);
    let pm = PermMap::new(&[1, 2], &[1, 2, -1], &[0.0]).unwrap();
    plot.add_frame(FrameRef::Current, Box::new(pm), Box::new(cube))
        .unwrap();
    plot
}

#[test]
fn a_three_dimensional_current_frame_is_drawn_through_two_axes() {
    let mut failures = Vec::new();
    let (log, svg) = log_and_svg(&car3_3d(), |plot, grf| plot.draw_grid(grf));
    compare(
        "car3_3d grid",
        &log,
        &svg,
        border::GRID_3D.0,
        (&border::GRID_3D.1).into(),
        &mut failures,
    );
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// A Plot that is not 2-D gives C's messages: a base Frame of three axes,
/// and a current Frame of one.
#[test]
fn drawing_a_plot_that_is_not_two_dimensional_gives_c_messages() {
    let mut plot = car3_3d();
    plot.set_base(FrameRef::Current).unwrap();
    let err = plot.draw_grid(&mut LogGrf::new(Vec::new())).unwrap_err();
    assert_eq!(err.code(), ErrorCode::Naxin);
    assert_eq!(
        err.message(),
        "astGrid(Plot): Number of axes (3) in the base Frame of the supplied Plot is invalid - \
         this number should be 2."
    );
    let mut plot = plot_of(None, [0.1, 0.1, 0.9, 0.9], [0.0, 0.0, 10.0, 10.0]);
    let pm = PermMap::new(&[1, -1], &[1], &[0.0]).unwrap();
    let one = Box::new(BasicFrameBuilder::new(1).build().unwrap());
    plot.add_frame(FrameRef::Current, Box::new(pm), one)
        .unwrap();
    let err = plot.draw_border(&mut LogGrf::new(Vec::new())).unwrap_err();
    assert_eq!(err.code(), ErrorCode::Naxin);
    assert_eq!(
        err.message(),
        "astBorder(Plot): Number of axes (1) in the current Frame of the supplied Plot is \
         invalid - this number should be 2."
    );
}

#[test]
fn borders_match_the_c_library() {
    let mut failures = Vec::new();
    for case in border::CASES {
        let plot = border_plot(case.name);
        let mut inval = None;
        let (log, svg) = log_and_svg(&plot, |plot, grf| {
            inval = Some(plot.draw_border(grf)?);
            Ok(())
        });
        if inval != Some(case.inval) {
            failures.push(format!(
                "{}: border gives {inval:?}, C gives {}",
                case.name, case.inval
            ));
        }
        compare(
            case.name,
            &log,
            &svg,
            case.log,
            (&case.svg).into(),
            &mut failures,
        );
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

